  // =========================================================================
  // Calculation Engine (Mirrored Client-Side for Instant Real-Time Feedback)
  // =========================================================================
  const CalculationEngine = {
    calculateItemArea: function(width, height, count, unit) {
      const w = parseFloat(width) || 0;
      const h = parseFloat(height) || 0;
      const qty = parseInt(count, 10) || 1;
      const u = (unit || 'm').toLowerCase();

      let singleArea = (u === 'mm') ? (w * h) / 1000000.0 : (w * h);
      let totalArea = singleArea * qty;

      return {
        unitAreaM2: Math.round(singleArea * 1000000) / 1000000,
        totalAreaM2: Math.round(totalArea * 1000000) / 1000000
      };
    },

    recalculateLine: function(item) {
      const qty = parseInt(item.count, 10) || 1;
      item.count = qty;

      const hasDims = (parseFloat(item.width) > 0 && parseFloat(item.height) > 0);
      if (!item.isManualArea && hasDims) {
        const areaInfo = this.calculateItemArea(item.width, item.height, qty, item.unit);
        item.unitAreaM2 = areaInfo.unitAreaM2;
        item.calculatedAreaM2 = areaInfo.totalAreaM2;
        item.billedAreaM2 = areaInfo.totalAreaM2;
      } else {
        // Direct Area Entry: either manual area or dimensions are not provided
        let area = 0;
        if (item.billedAreaM2 !== undefined && item.billedAreaM2 !== null && item.billedAreaM2 !== '') {
          area = parseFloat(item.billedAreaM2) || 0;
        } else if (item.calculatedAreaM2 !== undefined && item.calculatedAreaM2 !== null) {
          area = parseFloat(item.calculatedAreaM2) || 0;
        }
        item.billedAreaM2 = area;
        item.calculatedAreaM2 = area;
        item.unitAreaM2 = (qty > 0) ? (area / qty) : area;
      }

      const billableArea = (item.billedAreaM2 !== undefined && item.billedAreaM2 !== null)
        ? parseFloat(item.billedAreaM2)
        : item.calculatedAreaM2;

      const rate = parseFloat(item.unitRate) || 0;
      let isMin = false;
      let total = 0;

      // Rule (*) evaluation:
      const isRuleEnabled = (State.activeQuote.minChargeEnabled !== false);
      const minAmount = (State.activeQuote.minChargeAmount !== undefined) ? parseFloat(State.activeQuote.minChargeAmount) : 650.00;
      const minThreshold = (State.activeQuote.minChargeThreshold !== undefined) ? parseFloat(State.activeQuote.minChargeThreshold) : 1.000;
      const eligible = (item.category === 'Windows' || item.category === 'Doors');

      if (isRuleEnabled && eligible && item.unitAreaM2 < minThreshold && item.unitAreaM2 > 0) {
        isMin = true;
        total = qty * minAmount; // Flat SAR per unit
      } else {
        total = billableArea * rate;
      }

      item.isMinimumApplied = isMin;
      item.lineTotal = Math.round(total * 100) / 100;
      return item;
    },

    recalculateActiveQuote: function() {
      let subtotal = 0;
      let minCount = 0;

      State.activeQuote.items.forEach(itm => {
        this.recalculateLine(itm);
        subtotal += itm.lineTotal;
        if (itm.isMinimumApplied) minCount++;
      });

      subtotal = Math.round(subtotal * 100) / 100;
      const vatRate = (State.activeQuote.vatRate !== undefined) ? parseFloat(State.activeQuote.vatRate) : 0.15;
      const vatAmount = Math.round(subtotal * vatRate * 100) / 100;
      const grandTotal = Math.round((subtotal + vatAmount) * 100) / 100;

      State.activeQuote.subtotal = subtotal;
      State.activeQuote.vatAmount = vatAmount;
      State.activeQuote.grandTotal = grandTotal;
      State.activeQuote.minimumSurchargeCount = minCount;

      UI.updateSummaryBox();
    }
  };

